.memory-essay{max-width:720px;margin:0 auto;color:#3e443d;font-family:"Malgun Gothic","Apple SD Gothic Neo",sans-serif;font-size:18px;line-height:2.02;word-break:keep-all;overflow-wrap:break-word;letter-spacing:-.015em}.memory-essay p{margin:0 0 25px}.memory-essay .opening{font-family:"Batang","Noto Serif KR",serif;font-size:24px;line-height:1.85;color:#29483d;margin-bottom:30px}.memory-essay section{margin-top:76px}.memory-essay .section-label{color:#977854;font-size:12px;letter-spacing:.12em;font-weight:700;margin:0 0 13px}.memory-essay h2{font-family:"Batang","Noto Serif KR",serif;color:#29483d;font-size:28px;line-height:1.6;letter-spacing:-.035em;font-weight:700;margin:0 0 29px}.memory-essay strong{font-weight:700;color:#29483d}.memory-essay blockquote{margin:42px 0;padding:28px 32px;background:#eee8dc;border:0;border-left:3px solid #ad8b5e;color:#405246;font-family:"Batang","Noto Serif KR",serif;font-size:23px;line-height:1.85}.memory-essay .pullquote{background:#edf0e9;border-color:#90a38d;font-size:25px}.memory-essay .inline-figure{margin:55px -48px 65px}.memory-essay .inline-figure img{display:block;width:100%;height:auto;border-radius:4px}.memory-essay figcaption{font-size:13px;line-height:1.7;color:#80796c;margin:15px 14px 0;text-align:center}.memory-essay .ending{background:#eff1e8;padding:40px 42px;margin:76px -42px 0;border-radius:5px}.memory-essay .ending p{margin-bottom:24px}.memory-essay .last-line{font-family:"Batang","Noto Serif KR",serif;font-size:23px;line-height:1.9;padding-top:16px;margin-bottom:0!important}.memory-essay .essay-note{font-size:12px;line-height:1.8;color:#847e71;margin:45px 0 0;padding-top:21px;border-top:1px solid #ddd8ce}
@media(max-width:840px){.memory-essay .inline-figure{margin:42px 0 50px}.memory-essay .ending{margin:60px 0 0;padding:30px 26px}}
@media(max-width:520px){.memory-essay{font-size:16px;line-height:1.98}.memory-essay .opening{font-size:21px}.memory-essay section{margin-top:54px}.memory-essay h2{font-size:25px}.memory-essay blockquote{font-size:20px;padding:23px 22px}.memory-essay .pullquote{font-size:21px}.memory-essay .ending{padding:28px 22px}.memory-essay .last-line{font-size:21px}}
